'use strict'

const UPGRADE_DIR = '.cds-upgrade'
const REPORT_FILE = 'report.md'
const FINDINGS_FILE = 'report.yaml'
const JAVA_LATEST = require('../../lib/init/constants').MAVEN_ARCHETYPE_VERSION

// CDS dependencies to rewrite (Node.js)
const CDS_DEPS = ['@sap/cds', '@sap/cds-dk']

// Per-target overrides. Anything not listed here uses the generic rule
// (Node deps: ^${target}, no Java property changes).
const TARGET_OVERRIDES = {
  10: {
    node: {
      "@cap-js/cds-test": "^1",
      '@cap-js/hana': '^3',
      '@cap-js/sqlite': '^3',
      '@sap/cds-mtxs': '^4',
      '@sap/xssec': '^4'
    },
    java: {
      'cds.services.version': JAVA_LATEST,
      'cds.install-cdsdk.version': '10',
      'spring.boot.version': '4.1.0',
    },
  },
}

// Java cds.services.version major → CDS product major
const JAVA_CDS_MAJOR_MAP = { 4: 9, 5: 10 }

const TRACKED_MAJOR_MAP = {
  '@sap/cds':          null,
  '@sap/cds-dk':       null,
  '@sap/cds-mtxs':     { 3: 9, 4: 10 },
  '@sap/cds-compiler': { 6: 9, 7: 10 },
}

// Minimum Node.js major version recommended per cds target. Used to propose
// an `engines.node` bump for package.json when the declared range doesn't
// require at least this major.
const TARGET_MIN_NODE = {
  10: 22,
}

function targetMinNode(target) {
  return TARGET_MIN_NODE[target] ?? null
}

function rangeSatisfiesTarget(range, targetMajor) {
  if (range === undefined || range === null || range === '' || range === '*' || range === 'latest') return true
  const semver = require('semver')
  try {
    return semver.satisfies(`${targetMajor}.0.0`, range, { includePrerelease: true })
  } catch {
    return false
  }
}

// True iff the given engines.node range guarantees at least major `minMajor`.
// A missing/empty range fails the guarantee (caller should propose a bump).
function engineNodeMeetsMin(range, minMajor) {
  if (!range) return false
  const semver = require('semver')
  try {
    const min = semver.minVersion(range)
    return !!(min && min.major >= minMajor)
  } catch {
    return false
  }
}

function dependencyUpdatesFor(target) {
  const override = TARGET_OVERRIDES[target] || {}
  const node = {
    '@sap/cds': `^${target}`,
    '@sap/cds-dk': `^${target}`,
    ...(override.node || {}),
  }
  return {
    node,
    java: override.java || {},
  }
}

function javaCdsMajorFor(versionMajor) {
  return JAVA_CDS_MAJOR_MAP[versionMajor] ?? null
}

module.exports = {
  UPGRADE_DIR,
  REPORT_FILE,
  FINDINGS_FILE,
  CDS_DEPS,
  dependencyUpdatesFor,
  javaCdsMajorFor,
  TRACKED_MAJOR_MAP,
  rangeSatisfiesTarget,
  targetMinNode,
  engineNodeMeetsMin,
}
